// mTLS-Verbindung aus settings.js (functionGlobalContext.pgSsl)
const ssl = global.get('pgSsl');
if (!ssl) {
    node.error('pgSsl fehlt - functionGlobalContext in settings.js setzen (siehe README)', msg);
    return null;
}

msg.pgConfig = {
    host: 'postgres',      // <-- Postgres-Hostname anpassen (muss zum Server-Cert passen)
    port: 5432,
    database: 'messdaten',
    user: 'node-red',      // == CN des Client-Certs
    ssl                    // { ca, cert, key, rejectUnauthorized }
};

// --- Topic/Payload -> Messwert: AN DAS REALE modbus2mqtt-FORMAT ANPASSEN ---
// Annahme hier: zaehlernummer = letztes Topic-Segment, payload = Zahl ODER
// { value|wert, ts|timestamp }.
const parts = String(msg.topic || '').split('/');
const zaehlernummer = parts[parts.length - 1];

let wert, ts;
if (msg.payload && typeof msg.payload === 'object') {
    wert = Number(msg.payload.value ?? msg.payload.wert);
    ts = msg.payload.ts || msg.payload.timestamp;
} else {
    wert = Number(msg.payload);
}
const gemessenAm = ts ? new Date(ts).toISOString() : new Date().toISOString();

if (!zaehlernummer || Number.isNaN(wert)) {
    node.warn('verworfen: zaehlernummer/wert ungueltig (topic=' + msg.topic + ')');
    return null;
}

msg.params = [zaehlernummer, gemessenAm, wert];
return msg;
